- **Changed test signature** from callback pattern to async/Promise:

**Before:**
```javascript
test('sends 503 when heap threshold exceeded', function (t) {
  // ... setup ...
  req.on('response', function (res) {
    t.is(res.statusCode, 503)
    t.end()
  })
})
```

**After:**
```javascript
test('sends 503 when heap threshold exceeded', async () => {
  return new Promise((resolve, reject) => {
    // ... setup ...
    req.on('response', function (res) {
      try {
        expect(res.statusCode).toBe(503)
        resolve()
      } catch (err) {
        reject(err)
      }
    }).on('error', reject)
  })
})
```

- **Enhanced error handling** with try-catch blocks and `.on('error', reject)` on HTTP requests

